"use client";

import { useSyncExternalStore } from "react";
import type { Car } from "@/types/car";
import { parseDataset } from "@/lib/data/dataset";
import { createEngineContext, type EngineContext } from "@/lib/game/engine";

/** Static file generated by `pnpm catalogue`; kept available offline by the service worker. */
export const CATALOGUE_URL = "/catalogue.json";

export interface Catalogue {
  cars: readonly Car[];
  engine: EngineContext;
}

export type CatalogueState =
  | { status: "loading" }
  | { status: "ready"; catalogue: Catalogue }
  | { status: "error" };

let state: CatalogueState = { status: "loading" };
let started = false;
const listeners = new Set<() => void>();

function setState(next: CatalogueState) {
  state = next;
  listeners.forEach((l) => l());
}

async function load() {
  setState({ status: "loading" });
  try {
    const res = await fetch(CATALOGUE_URL);
    if (!res.ok) throw new Error(`${res.status}`);
    const { cars, errors } = parseDataset(await res.json());
    if (errors.length > 0 && process.env.NODE_ENV !== "production") {
      console.warn(`[calandre] ${errors.length} invalid catalogue entries ignored`, errors.slice(0, 20));
    }
    setState({ status: "ready", catalogue: { cars, engine: createEngineContext(cars) } });
  } catch {
    setState({ status: "error" });
  }
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  if (!started) {
    started = true;
    void load();
  }
  return () => listeners.delete(listener);
}

const SERVER_STATE: CatalogueState = { status: "loading" };

/** The car catalogue, loaded once per page lifetime and shared by every component. */
export function useCatalogue(): CatalogueState & { retry: () => void } {
  const current = useSyncExternalStore(
    subscribe,
    () => state,
    () => SERVER_STATE,
  );
  return { ...current, retry: () => void load() };
}
